  if (property.organizationId) {
    reviewTargets.push({
      type: 'organization',
      id: property.organizationId,
      titleAr: 'المؤسسة',
      titleEn: 'Organization',
    });
  }

  return (
    <main className="section">
      <div className="container">
        <PropertyDetailManager
          property={property}
          locale={locale}
          portal="owner"
          variant="public"
          signedIn={Boolean(viewer)}
