import fs from 'node:fs';

const path = 'docs/handoffs/2026-08-31-multi-unit-listing-cards/conversation-transcript-FULL.jsonl';
const out = 'docs/handoffs/2026-08-31-multi-unit-listing-cards/conversation-readable-FULL.md';
const lines = fs.readFileSync(path, 'utf8').split(/\r?\n/).filter(Boolean);

const md = [];
md.push('# نسخة مقروءة كاملة من محادثة Cursor');
md.push('');
md.push('- **المصدر:** conversation-transcript-FULL.jsonl (نسخة حرفية من ملف الـ transcript)');
md.push('- **تاريخ التوثيق:** 2026-08-31');
md.push('- **وقت التوثيق (مسقط / UTC+4):** 22:29');
md.push('- **معرّف المحادثة:** 307d3b18-d433-4130-9cd4-fbf9f887f158');
md.push(`- **عدد أسطر الـ JSONL:** ${lines.length}`);
md.push('');
md.push('> هذه النسخة تستخرج نصوص المستخدم والمساعد من كل حدث، دون حذف محتوى نصي داخل الرسائل.');
md.push('');

let i = 0;
for (const line of lines) {
  let ev;
  try {
    ev = JSON.parse(line);
  } catch {
    continue;
  }
  const role = ev.role || ev.message?.role || 'unknown';
  const msg = ev.message || ev;
  const content = msg.content;
  const texts = [];
  if (typeof content === 'string') texts.push(content);
  else if (Array.isArray(content)) {
    for (const part of content) {
      if (!part) continue;
      if (typeof part === 'string') texts.push(part);
      else if (part.type === 'text' && typeof part.text === 'string') texts.push(part.text);
      else if (part.type === 'image' || part.type === 'image_url') texts.push('[صورة مرفقة في المحادثة]');
      else if (part.type === 'tool_use') texts.push(`[tool_use: ${part.name || ''}]`);
      else if (part.type === 'tool_result') texts.push('[tool_result]');
    }
  }
  if (!texts.length) continue;
  i += 1;
  const title = role === 'user' ? 'المستخدم' : role === 'assistant' ? 'المساعد' : role;
  md.push('---');
  md.push('');
  md.push(`## ${i}. ${title}`);
  md.push('');
  md.push(texts.join('\n\n'));
  md.push('');
}

fs.writeFileSync(out, md.join('\n'), 'utf8');
console.log(`messages=${i} bytes=${fs.statSync(out).size}`);

import 'server-only';
import { sql, type ExtractTablesWithRelations } from 'drizzle-orm';
import type { PgTransaction } from 'drizzle-orm/pg-core';
import type { PostgresJsQueryResultHKT } from 'drizzle-orm/postgres-js';
import type * as schema from '@bhd-r/db/schema';

type AppTx = PgTransaction<
  PostgresJsQueryResultHKT,
  typeof schema,
  ExtractTablesWithRelations<typeof schema>
>;

/**
 * Production may lag behind schema commits. Idempotent ALTER so profile
 * reads/writes do not fail with "column does not exist".
 */
export async function ensurePropertyProfileListingColumns(transaction: {
  execute: AppTx['execute'];
}): Promise<void> {
  await transaction.execute(sql`
    ALTER TABLE "property_profiles"
    ADD COLUMN IF NOT EXISTS "show_owner_name_on_listing" boolean NOT NULL DEFAULT false
  `);
}

import 'server-only';
import { sql } from 'drizzle-orm';

type Executable = {
