import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { setRequestLocale } from 'next-intl/server';
import { Link } from '@/i18n/navigation';
import { StayCheckout } from '@/components/stays/stay-checkout';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { localizedName } from '@/lib/format';
import { loadPublicStayBySlugOnNeon } from '@/lib/load-public-stays-neon';
import { toPublicMediaSrc } from '@/lib/public-media-url';
import { isStaysPublicSurfaceEnabled } from '@/lib/stays-flags';
import { publicApiFetch } from '@/lib/server-api';
import { getViewer } from '@/lib/viewer';
import type { StayPublicDetail } from '@bhd-r/contracts';

type StayType = 'overnight_stay' | 'day_use' | 'overnight_only';

function pickQuery(
  query: Record<string, string | string[] | undefined>,
  key: string,
): string | undefined {
  const raw = query[key];
  if (typeof raw === 'string' && raw.trim()) return raw.trim();
  if (Array.isArray(raw) && typeof raw[0] === 'string' && raw[0].trim()) return raw[0].trim();
  return undefined;
}

function parseStayType(value: string | undefined): StayType | undefined {
  if (value === 'day_use' || value === 'overnight_only' || value === 'overnight_stay') return value;
  return undefined;
}

async function loadStayDetail(
  slug: string,
  unitId?: string,
): Promise<StayPublicDetail | null> {
  if (hasDatabaseUrl()) {
    try {
      const neon = await loadPublicStayBySlugOnNeon(slug, unitId ?? null);
      if (neon) return neon;
    } catch (error) {
      console.error('Neon public stay load failed', error);
    }
  }
  const qs = unitId ? `?unitId=${encodeURIComponent(unitId)}` : '';
  return publicApiFetch<StayPublicDetail>(
    `/v1/public/stays/${encodeURIComponent(slug)}${qs}`,
    8,
  ).catch(() => null);
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ locale: string; slug: string }>;
}): Promise<Metadata> {
  const { locale, slug } = await params;
  const detail = await loadStayDetail(slug).catch(() => null);
  const title = detail
    ? localizedName(locale, detail.titleAr, detail.titleEn)
    : locale === 'ar'
      ? 'إكمال الحجز'
      : 'Complete booking';
  return {
    title: locale === 'ar' ? `حجز — ${title}` : `Book — ${title}`,
    robots: { index: false, follow: false },
  };
}

/** Dedicated Booking.com-style checkout page (not embedded in the property page). */
export default async function StayBookPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string; slug: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  if (!isStaysPublicSurfaceEnabled()) notFound();
  const { locale: rawLocale, slug } = await params;
  const locale = rawLocale === 'en' ? 'en' : 'ar';
  const query = await searchParams;
  setRequestLocale(locale);
  const ar = locale === 'ar';
  const unitId = pickQuery(query, 'unit') ?? pickQuery(query, 'unitId');

  const [detail, viewer] = await Promise.all([loadStayDetail(slug, unitId), getViewer()]);
  if (!detail) notFound();

  const title = localizedName(locale, detail.titleAr, detail.titleEn);
  const cover = toPublicMediaSrc(detail.coverImageUrl) ?? detail.coverImageUrl ?? null;
  const stayType = parseStayType(pickQuery(query, 'stayType'));

  return (
    <div className="container section stays-book-page">
      <div className="stays-book-page__layout">
        <aside className="stays-book-page__aside">
          <Link
            className="stays-book-page__back"
            href={`/stays/${encodeURIComponent(slug)}${unitId ? `?unit=${encodeURIComponent(unitId)}` : ''}`}
          >
            {ar ? '← العودة للإقامة' : '← Back to stay'}
          </Link>
          {cover ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img className="stays-book-page__cover" src={cover} alt="" />
          ) : null}
          <h1 className="stays-book-page__title">{title}</h1>
          <p className="muted">
            {ar
              ? 'راجع التواريخ ونوع الإقامة ثم أكمل بياناتك في صفحة مستقلة — كما في مواقع الحجز العالمية.'
              : 'Review dates and stay type, then complete guest details on a dedicated page — like global booking sites.'}
          </p>
        </aside>
        <div className="stays-book-page__main">
          <StayCheckout
            locale={locale}
            slug={slug}
            title={title}
            {...((detail.unitId ?? unitId) ? { unitId: (detail.unitId ?? unitId)! } : {})}
            defaults={{
              ...(pickQuery(query, 'checkInOn')
                ? { checkInOn: pickQuery(query, 'checkInOn')! }
                : {}),
              ...(pickQuery(query, 'checkOutOn')
                ? { checkOutOn: pickQuery(query, 'checkOutOn')! }
                : {}),
              ...(pickQuery(query, 'adults') ? { adults: pickQuery(query, 'adults')! } : {}),
              ...(pickQuery(query, 'children')
                ? { children: pickQuery(query, 'children')! }
                : {}),
              ...(stayType ? { stayType } : {}),
              ...(viewer?.displayName?.trim() ? { guestName: viewer.displayName.trim() } : {}),
              ...(viewer?.email?.trim() ? { guestEmail: viewer.email.trim() } : {}),
            }}
          />
        </div>
      </div>
    </div>
  );
}

input.contents:
import { setRequestLocale } from 'next-intl/server';
import { notFound } from 'next/navigation';
import { Link } from '@/i18n/navigation';
import { RememberStayTripAlert } from '@/components/stays/remember-stay-trip-alert';
import { formatMoney } from '@/lib/format';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { lookupPublicStayBookingOnNeon } from '@/lib/public-stays-guest-neon';
import { isStaysPublicSurfaceEnabled } from '@/lib/stays-flags';
import { publicApiFetch } from '@/lib/server-api';

type PublicBooking = {
  id?: string;
  referenceCode: string;
  status: string;
  checkInOn?: string;
  checkOutOn?: string;
  currency?: string;
  totalMinor?: string;
  nights?: number;
  guestDisplayName?: string | null;
  guestEmail?: string | null;
  adults?: number | null;
  children?: number | null;
  stayType?: string | null;
};

function stayTypeLabel(type: string | null | undefined, ar: boolean): string {
  if (type === 'day_use') return ar ? 'إقامة بدون مبيت' : 'Day use';
  if (type === 'overnight_only') return ar ? 'مبيت فقط' : 'Overnight only';
  if (type === 'overnight_stay') return ar ? 'إقامة مع مبيت' : 'Stay with overnight';
  return type ?? '—';
}

async function loadBooking(ref: string): Promise<PublicBooking | null> {
  if (hasDatabaseUrl()) {
    try {
      return await lookupPublicStayBookingOnNeon(ref);
    } catch {
      // fall through to Nest rewrite
    }
  }
  return publicApiFetch<PublicBooking>(
    `/v1/public/stays/bookings/lookup?referenceCode=${encodeURIComponent(ref)}`,
    8,
  ).catch(() => null);
}

export default async function StayBookingConfirmedPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  if (!isStaysPublicSurfaceEnabled()) notFound();
  const { locale } = await params;
  const query = await searchParams;
  setRequestLocale(locale);
  const ar = locale === 'ar';

  const refRaw = query.ref;
  const ref =
    typeof refRaw === 'string' ? refRaw : Array.isArray(refRaw) ? refRaw[0] : undefined;
  if (!ref) notFound();

  const booking = await loadBooking(ref);
  if (!booking) notFound();

  const paid = booking.status === 'confirmed' || booking.status === 'paid';
  const stayTone =
    booking.stayType === 'day_use' || booking.stayType === 'overnight_only'
      ? booking.stayType
      : 'overnight_stay';

  return (
    <div className="container section stays-booking-confirmed">
      <RememberStayTripAlert
        id={booking.id ?? booking.referenceCode}
        referenceCode={booking.referenceCode}
        status={booking.status}
        {...(booking.checkInOn ? { checkInOn: booking.checkInOn } : {})}
        {...(booking.checkOutOn ? { checkOutOn: booking.checkOutOn } : {})}
        {...(booking.currency ? { currency: booking.currency } : {})}
        {...(booking.totalMinor ? { totalMinor: booking.totalMinor } : {})}
      />
      <section className="stays-checkout stays-checkout--wizard stays-booking-confirmed__shell">
        <h1 id="stays-booking-confirmed-title">
          {ar ? 'تم استلام حجزك' : 'Your booking is received'}
        </h1>
        <p className="muted stays-checkout__hint">
          {paid
            ? ar
              ? 'تم تأكيد الحجز والدفع. يمكنك فتح إيصال الدفع وحفظه كملف PDF.'
              : 'Booking and payment are confirmed. Open the receipt and save it as PDF.'
            : ar
              ? 'الحجز مسجّل. أكمل الدفع لتأكيد الإقامة.'
              : 'Booking is registered. Complete payment to confirm your stay.'}
        </p>

        <div className="stays-checkout__panel">
          <dl className="stays-checkout__summary">
            <div>
              <dt>{ar ? 'مرجع الحجز' : 'Booking reference'}</dt>
              <dd dir="ltr">
                <strong>{booking.referenceCode}</strong>
              </dd>
            </div>
            {booking.guestDisplayName ? (
              <div>
                <dt>{ar ? 'الضيف' : 'Guest'}</dt>
                <dd>{booking.guestDisplayName}</dd>
              </div>
            ) : null}
            {booking.checkInOn ? (
              <div>
                <dt>{ar ? 'الوصول' : 'Check-in'}</dt>
                <dd className="stays-checkout__chip stays-checkout__chip--check-in" dir="ltr">
                  {booking.checkInOn}
                </dd>
              </div>
            ) : null}
            {booking.checkOutOn ? (
              <div>
                <dt>{ar ? 'المغادرة' : 'Check-out'}</dt>
                <dd className="stays-checkout__chip stays-checkout__chip--check-out" dir="ltr">
                  {booking.checkOutOn}
                </dd>
              </div>
            ) : null}
            {booking.stayType ? (
              <div>
                <dt>{ar ? 'نوع الحجز' : 'Stay type'}</dt>
                <dd className={`stays-checkout__chip stays-checkout__chip--stay-${stayTone}`}>
                  {stayTypeLabel(booking.stayType, ar)}
                </dd>
              </div>
            ) : null}
            {typeof booking.adults === 'number' ? (
              <div>
                <dt>{ar ? 'بالغون' : 'Adults'}</dt>
                <dd className="stays-checkout__chip stays-checkout__chip--adults">{booking.adults}</dd>
              </div>
            ) : null}
            {typeof booking.children === 'number' ? (
              <div>
                <dt>{ar ? 'أطفال' : 'Children'}</dt>
                <dd className="stays-checkout__chip stays-checkout__chip--children">
                  {booking.children}
                </dd>
              </div>
            ) : null}
            {booking.totalMinor && booking.currency ? (
              <div>
                <dt>{ar ? 'المجموع' : 'Total'}</dt>
                <dd dir="ltr">
                  <strong>{formatMoney(booking.totalMinor, booking.currency, locale)}</strong>
                </dd>
              </div>
            ) : null}
            <div>
              <dt>{ar ? 'الحالة' : 'Status'}</dt>
