.stay-confirm-shell {
  --confirm-pad: clamp(1rem, 3vw, 2rem);
  min-height: 100dvh;
  width: 100%;
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto 1fr;
  background:
    radial-gradient(ellipse 80% 50% at 10% 0%, rgba(15, 118, 110, 0.12), transparent 55%),
    linear-gradient(165deg, #f4f7f5 0%, #e8efeb 50%, #f7f4ee 100%);
}
.stay-confirm-shell__aside {
  position: relative;
  min-height: clamp(14rem, 42vw, 18rem);
  overflow: hidden;
  color: #f5fbf8;
}
.stay-confirm-shell__aside-inner {
  position: relative;
  isolation: isolate;
  min-height: inherit;
  height: 100%;
}
.stay-confirm-shell__aside-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  z-index: 0;
}
.stay-confirm-shell__aside-scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(
    160deg,
    rgba(8, 36, 30, 0.55) 0%,
    rgba(10, 55, 48, 0.62) 48%,
    rgba(5, 22, 18, 0.88) 100%
  );
}
.stay-confirm-shell__aside-content {
  position: relative;
  z-index: 2;
  display: grid;
  gap: 0.55rem;
  align-content: end;
  min-height: inherit;
  padding: max(var(--confirm-pad), env(safe-area-inset-top)) var(--confirm-pad) 1.25rem;
}
.stay-confirm-shell__brand {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.stay-confirm-shell__badge {
  width: fit-content;
  margin: 0;
  padding: 0.22rem 0.55rem;
  border-radius: 0.4rem;
  background: rgba(255, 255, 255, 0.16);
  font-size: 0.72rem;
  font-weight: 700;
}
.stay-confirm-shell__aside h1 {
  margin: 0.15rem 0 0;
  font-size: clamp(1.45rem, 4.5vw, 2rem);
  line-height: 1.2;
  color: #fff;
}
.stay-confirm-shell__lede {
  margin: 0;
  max-width: 34ch;
  color: rgba(245, 251, 248, 0.88);
  font-size: 0.95rem;
  line-height: 1.5;
}
.stay-confirm-shell__amount {
  margin: 0.35rem 0 0;
  font-size: clamp(1.6rem, 5vw, 2.1rem);
  font-weight: 800;
  letter-spacing: -0.02em;
}
.stay-confirm-shell__ref {
  margin: 0;
  font-size: 0.86rem;
  font-weight: 700;
  opacity: 0.9;
}
.stay-confirm-shell__panel {
  width: min(100%, 42rem);
  margin: 0 auto;
  padding: 1.25rem
    max(var(--confirm-pad), env(safe-area-inset-right))
    max(var(--confirm-pad), env(safe-area-inset-bottom))
    max(var(--confirm-pad), env(safe-area-inset-left));
}
.stay-confirm-shell__header {
  margin-bottom: 1rem;
}
.stay-confirm-shell__header h2 {
  margin: 0 0 0.25rem;
  font-size: clamp(1.15rem, 3.2vw, 1.4rem);
  color: var(--oman-deep, #092d24);
}
.stay-confirm-shell__header .muted {
  margin: 0;
}
.stay-confirm-shell__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem 1rem;
  margin: 0 0 1.15rem;
  padding: 1.1rem;
  border-radius: 1rem;
  background: #fff;
  border: 1px solid color-mix(in srgb, var(--oman-deep) 10%, #d7e1db);
  box-shadow: 0 14px 30px rgba(9, 45, 36, 0.06);
}
.stay-confirm-shell__grid dt {
  font-size: 0.74rem;
  color: var(--muted, #5c6b64);
}
.stay-confirm-shell__grid dd {
  margin: 0.2rem 0 0;
  font-weight: 700;
}
.stay-confirm-shell__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin-bottom: 0.85rem;
}
.stay-confirm-shell__actions .button {
  flex: 1 1 10rem;
  justify-content: center;
  text-align: center;
}
.stay-confirm-shell__hint {
  margin: 0.45rem 0 0;
  font-size: 0.86rem;
}
@media (max-width: 640px) {
  .stay-confirm-shell__grid {
    grid-template-columns: 1fr;
  }
}
@media (min-width: 900px) {
  .stay-confirm-shell {
    grid-template-columns: minmax(18rem, 0.95fr) minmax(24rem, 1.1fr);
    grid-template-rows: 1fr;
  }
  .stay-confirm-shell__aside {
    min-height: 100dvh;
  }
  .stay-confirm-shell__aside-content {
    max-width: 28rem;
    margin-inline: auto;
    min-height: 100dvh;
    padding: var(--confirm-pad);
  }
  .stay-confirm-shell__panel {
    width: 100%;
    max-width: none;
    display: grid;
    align-content: center;
    padding: var(--confirm-pad) clamp(1.5rem, 5vw, 4rem);
    background: rgba(255, 255, 255, 0.55);
    backdrop-filter: blur(10px);
  }
  .stay-confirm-shell__grid {
    max-width: 34rem;
  }
  .stay-confirm-shell__actions {
    max-width: 34rem;
  }
}

