import { formatMoney } from '@/lib/format';

export type StayBookingDocumentData = {
  referenceCode: string;
  status: string;
  checkInOn?: string;
  checkOutOn?: string;
  currency?: string;
  totalMinor?: string;
  nights?: number | null;
  guestDisplayName?: string | null;
  guestEmail?: string | null;
  adults?: number | null;
  children?: number | null;
  stayType?: string | null;
};

export type StayBookingDocumentKind = 'payment' | 'confirmation';

function stayTypeLabel(type: string | null | undefined, ar: boolean): string {
  if (type === 'day_use') return ar ? 'إقامة بدون مبيت' : 'Day use';
  if (type === 'overnight_only') return ar ? 'مبيت فقط' : 'Overnight only';
  if (type === 'overnight_stay') return ar ? 'إقامة مع مبيت' : 'Stay with overnight';
  return type ?? '—';
}

function statusLabel(status: string, paid: boolean, ar: boolean): string {
  if (status === 'payment_pending' || status === 'request_pending') {
    return ar ? 'بانتظار الدفع' : 'Awaiting payment';
  }
  if (paid) return ar ? 'مؤكّد / مدفوع' : 'Confirmed / paid';
  return status;
}

function Row({
  label,
  value,
  ltr,
}: {
  label: string;
  value: React.ReactNode;
  ltr?: boolean;
}) {
  return (
    <div className="stay-doc__row">
      <dt>{label}</dt>
      <dd dir={ltr ? 'ltr' : undefined}>{value}</dd>
    </div>
  );
}

export function StayBookingDocument({
  kind,
  booking,
  locale,
}: {
  kind: StayBookingDocumentKind;
  booking: StayBookingDocumentData;
  locale: string;
}) {
  const ar = locale === 'ar';
  const paid = booking.status === 'confirmed' || booking.status === 'paid';
  const title =
    kind === 'payment'
      ? ar
        ? 'إيصال دفع'
        : 'Payment receipt'
      : ar
        ? 'تأكيد حجز'
        : 'Booking confirmation';
  const subtitle =
    kind === 'payment'
      ? ar
        ? 'مستند رسمي لاستلام مبلغ حجز إقامة عبر BHD R'
        : 'Official record of stay booking payment via BHD R'
      : ar
        ? 'مستند رسمي لتأكيد تفاصيل حجز الإقامة'
        : 'Official confirmation of stay booking details';
  const amountLabel =
    booking.totalMinor && booking.currency
      ? formatMoney(booking.totalMinor, booking.currency, locale)
      : null;
  const issuedOn = new Intl.DateTimeFormat(ar ? 'ar-OM' : 'en-GB', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date());

  return (
    <article className="stay-doc" id="stay-receipt" data-doc-kind={kind}>
      <header className="stay-doc__header">
        <div className="stay-doc__brand">
          <span className="stay-doc__logo logo__product" aria-hidden="true">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src="/brand/bhd-official-symbol.svg" alt="" width="88" height="28" />
            <i>R</i>
          </span>
          <div>
            <p className="stay-doc__product">BHD R</p>
            <p className="stay-doc__tagline">A BHD Product · عمان</p>
          </div>
        </div>
        <div className="stay-doc__meta">
          <p className="stay-doc__kind">{title}</p>
          <p className="stay-doc__number" dir="ltr">
            {booking.referenceCode}
          </p>
          <p className="stay-doc__issued">
            {ar ? 'تاريخ الإصدار' : 'Issued'} · {issuedOn}
          </p>
        </div>
      </header>

      <p className="stay-doc__subtitle">{subtitle}</p>

      <div className="stay-doc__badge" data-paid={paid ? 'true' : 'false'}>
        {statusLabel(booking.status, paid, ar)}
      </div>

      <dl className="stay-doc__grid">
        {booking.guestDisplayName ? (
          <Row label={ar ? 'الضيف' : 'Guest'} value={booking.guestDisplayName} />
        ) : null}
        {booking.guestEmail ? (
          <Row label={ar ? 'البريد' : 'Email'} value={booking.guestEmail} ltr />
        ) : null}
        {booking.checkInOn ? (
          <Row label={ar ? 'الوصول' : 'Check-in'} value={booking.checkInOn} ltr />
        ) : null}
        {booking.checkOutOn ? (
          <Row label={ar ? 'المغادرة' : 'Check-out'} value={booking.checkOutOn} ltr />
        ) : null}
        {typeof booking.nights === 'number' ? (
          <Row
            label={ar ? 'عدد الليالي' : 'Nights'}
            value={`${booking.nights} ${
              ar
                ? booking.nights === 1
                  ? 'ليلة'
                  : 'ليالٍ'
                : booking.nights === 1
                  ? 'night'
                  : 'nights'
            }`}
          />
        ) : null}
        {booking.stayType ? (
          <Row label={ar ? 'نوع الحجز' : 'Stay type'} value={stayTypeLabel(booking.stayType, ar)} />
        ) : null}
        {typeof booking.adults === 'number' ? (
          <Row label={ar ? 'بالغون' : 'Adults'} value={String(booking.adults)} />
        ) : null}
        {typeof booking.children === 'number' ? (
          <Row label={ar ? 'أطفال' : 'Children'} value={String(booking.children)} />
        ) : null}
      </dl>

      {amountLabel ? (
        <div className="stay-doc__total">
          <span>{kind === 'payment' ? (ar ? 'المبلغ المستلم' : 'Amount received') : ar ? 'إجمالي الحجز' : 'Booking total'}</span>
          <strong dir="ltr">{amountLabel}</strong>
        </div>
      ) : null}

      <footer className="stay-doc__footer">
        <p>
          {kind === 'payment'
            ? ar
              ? 'يُعدّ هذا المستند إيصالاً مالياً لعملية الدفع المرتبطة برقم الحجز أعلاه.'
              : 'This document is a financial receipt for the payment linked to the booking reference above.'
            : ar
              ? 'يُعدّ هذا المستند تأكيداً رسمياً لتفاصيل الحجز. يُرجى الاحتفاظ به ليوم الوصول.'
              : 'This document is an official confirmation of the booking details. Please keep it for check-in.'}
        </p>
        <p className="stay-doc__thanks">
          {ar ? 'شكراً لاختياركم BHD R' : 'Thank you for choosing BHD R'}
        </p>
      </footer>
    </article>
  );
}

import { setRequestLocale } from 'next-intl/server';
import { notFound } from 'next/navigation';
import { Link } from '@/i18n/navigation';
import {
  StayBookingDocument,
  type StayBookingDocumentKind,
} from '@/components/stays/stay-booking-document';
import { StayReceiptPrintButton } from '@/components/stays/stay-receipt-print-button';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { lookupPublicStayBookingOnNeon } from '@/lib/public-stays-guest-neon';
import { isStaysPublicSurfaceEnabled } from '@/lib/stays-flags';
import { publicApiFetch } from '@/lib/server-api';

type PublicBooking = {
  id?: string;
  referenceCode: string;
  status: string;
  checkInOn?: string;
  checkOutOn?: string;
  currency?: string;
  totalMinor?: string;
  nights?: number;
  guestDisplayName?: string | null;
  guestEmail?: string | null;
  adults?: number | null;
  children?: number | null;
  stayType?: string | null;
};

async function loadBooking(ref: string): Promise<PublicBooking | null> {
  if (hasDatabaseUrl()) {
    try {
      return await lookupPublicStayBookingOnNeon(ref);
    } catch {
      /* fall through */
    }
  }
  return publicApiFetch<PublicBooking>(
    `/v1/public/stays/bookings/lookup?referenceCode=${encodeURIComponent(ref)}`,
    8,
  ).catch(() => null);
}

function resolveDocKind(raw: string | string[] | undefined): StayBookingDocumentKind {
  const value = typeof raw === 'string' ? raw : Array.isArray(raw) ? raw[0] : undefined;
  return value === 'confirmation' ? 'confirmation' : 'payment';
}

export default async function StayBookingReceiptPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  if (!isStaysPublicSurfaceEnabled()) notFound();
  const { locale } = await params;
  const query = await searchParams;
  setRequestLocale(locale);
  const ar = locale === 'ar';

  const refRaw = query.ref;
  const ref = typeof refRaw === 'string' ? refRaw : Array.isArray(refRaw) ? refRaw[0] : undefined;
  if (!ref) notFound();

  const booking = await loadBooking(ref);
  if (!booking) notFound();

  const kind = resolveDocKind(query.doc);
  const otherKind: StayBookingDocumentKind = kind === 'payment' ? 'confirmation' : 'payment';
  const title =
    kind === 'payment'
      ? ar
        ? 'إيصال الدفع'
        : 'Payment receipt'
      : ar
        ? 'تأكيد الحجز'
        : 'Booking confirmation';
  const otherLabel =
    otherKind === 'payment'
      ? ar
        ? 'إيصال الدفع'
        : 'Payment receipt'
      : ar
        ? 'تأكيد الحجز'
        : 'Booking confirmation';

  return (
    <div className="container section stays-booking-receipt">
      <div className="stays-booking-receipt__actions">
        <StayReceiptPrintButton
          locale={locale}
          label={ar ? 'تنزيل / طباعة PDF' : 'Download / print PDF'}
        />
        <Link
          className="button button--quiet"
          href={`/stays/booking/receipt?ref=${encodeURIComponent(ref)}&doc=${otherKind}`}
        >
          {otherLabel}
        </Link>
        <Link
          className="button button--quiet"
          href={`/stays/booking/confirmed?ref=${encodeURIComponent(ref)}`}
        >
          {ar ? 'العودة للتأكيد' : 'Back to confirmation'}
        </Link>
      </div>

      <header className="stays-booking-receipt__page-head">
        <h1 className="stays-booking-receipt__page-title">{title}</h1>
        <p className="muted">
          {ar
            ? 'مستند جاهز للطباعة أو الحفظ كملف PDF بنفس أسلوب الإيصالات الرسمية.'
            : 'Print-ready document — save as PDF in the same style as official receipts.'}
        </p>
      </header>

      <StayBookingDocument kind={kind} booking={booking} locale={locale} />
    </div>
  );
}

'use client';

export function StayReceiptPrintButton({
  locale,
  label,
}: {
  locale: string;
  label?: string;
}) {
  const ar = locale === 'ar';
  return (
    <button type="button" className="button button--primary" onClick={() => window.print()}>
      {label ?? (ar ? 'حفظ / طباعة PDF' : 'Save / print PDF')}
    </button>
  );
}

