  color: #0b6e4f;
  border: 1px solid color-mix(in srgb, #0b6e4f 28%, transparent);
}
.stay-doc__badge[data-paid='false'] {
  background: #fff4e8;
  color: #b45309;
  border-color: color-mix(in srgb, #b45309 28%, transparent);
}
.stay-doc__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  margin: 0;
  border: 1px solid var(--stay-doc-line);
  border-radius: 0.65rem;
  overflow: hidden;
}
.stay-doc__row {
  display: grid;
  grid-template-columns: minmax(6.5rem, 38%) 1fr;
  gap: 0.55rem;
  padding: 0.72rem 0.85rem;
  border-block-end: 1px solid var(--stay-doc-line);
  background: #fff;
}
.stay-doc__row:nth-child(odd) {
  background: #f8faf9;
}
.stay-doc__row:nth-last-child(-n + 2) {
  border-block-end: none;
}
.stay-doc__row dt {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 700;
  color: #5c6b64;
}
.stay-doc__row dd {
  margin: 0;
  font-weight: 700;
  font-size: 0.95rem;
}
.stay-doc__total {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  margin: 1rem 0 0;
  padding: 0.95rem 1rem;
  border-radius: 0.65rem;
  background: linear-gradient(135deg, #0a3a31 0%, #0f766e 100%);
  color: #f5fbf8;
}
.stay-doc__total span {
  font-size: 0.88rem;
  font-weight: 700;
  opacity: 0.92;
}
.stay-doc__total strong {
  font-size: clamp(1.35rem, 3.5vw, 1.75rem);
  font-weight: 800;
  letter-spacing: -0.01em;
}
.stay-doc__footer {
  margin: 1rem 0 0;
  padding-top: 0.85rem;
  border-top: 1px dashed var(--stay-doc-line);
}
.stay-doc__footer p {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.55;
  color: #44554d;
}
.stay-doc__thanks {
  margin-top: 0.55rem !important;
  font-weight: 800;
  color: var(--oman-deep, #092d24) !important;
}
@media (max-width: 640px) {
  .stay-doc__grid {
    grid-template-columns: 1fr;
  }
  .stay-doc__row:nth-last-child(-n + 2) {
    border-block-end: 1px solid var(--stay-doc-line);
  }
  .stay-doc__row:last-child {
    border-block-end: none;
  }
  .stay-doc__meta {
    text-align: start;
    width: 100%;
  }
}
@media print {
  .site-header,
  .site-footer,
  .stays-booking-receipt__actions,
  .stays-booking-receipt__page-head,
  .stays-booking-confirmed__review-hint {
    display: none !important;
  }
  .stays-booking-receipt {
    max-width: none;
    margin: 0;
  }
  .stay-doc {
    box-shadow: none;
    border-color: #bbb;
    border-radius: 0;
    padding: 0;
  }
  .stay-doc__total {
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }
}

